<div class="admin-page-head"><h1>دسته‌بندی‌های محصولات</h1><?= CHtml::link('+ دسته‌بندی جدید',array('adminCategory/create'),array('class'=>'btn btn-primary')) ?></div><section class="panel"><table class="data-table"><thead><tr><th>دسته‌بندی</th><th>آدرس</th><th>ترتیب</th><th></th></tr></thead><tbody><?php foreach(Hierarchy::flatten(Hierarchy::rows('categories')) as $row): ?><tr><td><?= CHtml::encode(str_repeat('— ',$row['_depth']).$row['name']) ?></td><td><?= CHtml::encode($row['slug']) ?></td><td><?= (int)$row['sort_order'] ?></td><td><?= CHtml::link('ویرایش',array('adminCategory/update','id'=>$row['id'])) ?></td></tr><?php endforeach; ?></tbody></table></section>
